export{ModalMedidaCtrl};function ModalMedidaCtrl($scope,$uibModalInstance,medidaSvc,tS,params){$scope.tipoRegistro=1,$scope.data={},params&&params.idMedida>0&&($scope.tipoRegistro=2,$scope.data=Object.assign({},params),$scope.showStatus=!params.estado),$scope.saveAndUpdate=function(){try{const tituloToast=1==$scope.tipoRegistro?"Guardar":"Actualizar";if(!$scope.data.descripcion)return void tS.toastr("warning","Ingrese la Descripción",tituloToast);showLoader(),$scope.data.idMedida>0?medidaSvc.update($scope.data.idMedida,$scope.data).then($scope.successReponse).catch(err=>{hideLoader(),console.log(err)}):medidaSvc.save($scope.data).then($scope.successReponse).catch(err=>{hideLoader(),console.log(err)})}catch(error){console.log(error),hideLoader()}},$scope.successReponse=function(response){hideLoader(),"0"===response.code&&tS.toastr("warning",response.message,response.titleSms),"1"===response.code&&(tS.toastr("success",response.message,response.titleSms),$uibModalInstance.close(response))},$scope.closeModal=function(){$uibModalInstance.close()}}ModalMedidaCtrl.$inject=["$scope","$uibModalInstance","medidaService","toastService","params"];